BEGIN; CREATE TABLE result(seq INTEGER,source INTEGER,r INTEGER,i INTEGER,t TEXT); WITH RECURSIVE q(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM q WHERE n<9999) INSERT INTO result SELECT q.n,1,v1.rowid,v1.i,v1.t FROM q JOIN v1 ON v1.rowid=q.n*3 WHERE q.n%3=0 UNION ALL SELECT q.n,2,v2.rowid,v2.i,v2.t FROM q JOIN v2 ON v2.rowid=q.n*3 WHERE q.n%3=1 UNION ALL SELECT q.n,3,v3.rowid,v3.i,v3.t FROM q JOIN v3 ON v3.rowid=q.n*3 WHERE q.n%3=2; COMMIT;